import SwiftUI
struct ProfileView: View {
    @EnvironmentObject private var auth: AuthStore; @Environment(\.dismiss) private var dismiss; @State private var showingLogoutAlert = false
    private var user: UserModel { auth.currentUser ?? UserModel(name: "Usuario", email: "user@bbva.pe", password: "") }
    var body: some View {
        ZStack { BBVA.navy.ignoresSafeArea(edges: .top); BBVA.sand.ignoresSafeArea(edges: .bottom); ScrollView { VStack(spacing: 0) { headerSection; infoSection; menuSection; settingsSection; logoutButton }.padding(.horizontal, 20).padding(.top, 20).padding(.bottom, 40) } }
        .navigationBarBackButtonHidden(true).toolbar { ToolbarItem(placement: .topBarLeading) { Button { Haptics.tap(); dismiss() } label: { HStack(spacing: 8) { Image(systemName: "chevron.left").font(.system(size: 16, weight: .semibold)); Text("Volver").font(BBVAFont.body(16, .demi)) }.foregroundColor(.white) } } }
        .alert("¿Cerrar sesión?", isPresented: $showingLogoutAlert) { Button("Cancelar", role: .cancel) {}; Button("Cerrar sesión", role: .destructive) { auth.logout() } } message: { Text("Volverás al inicio de sesión.") }
    }
    private var headerSection: some View { VStack(spacing: 16) { ZStack { Circle().fill(LinearGradient(colors: [BBVA.aqua, BBVA.lightBlue], startPoint: .topLeading, endPoint: .bottomTrailing)).frame(width: 120, height: 120).overlay(Circle().stroke(Color.white.opacity(0.3), lineWidth: 3)).shadow(color: BBVA.navy.opacity(0.3), radius: 20, y: 10); Text(String(user.firstName.prefix(1)).uppercased()).font(BBVAFont.title(56)).foregroundColor(BBVA.navy) }; VStack(spacing: 4) { Text(user.name).font(BBVAFont.title(28)).foregroundColor(.white); Text(user.email).font(BBVAFont.body(15)).foregroundColor(.white.opacity(0.7)) }; HStack(spacing: 8) { Image(systemName: "checkmark.seal.fill").foregroundColor(BBVA.aqua); Text("Cliente Verificado").font(BBVAFont.body(13, .medium)).foregroundColor(.white.opacity(0.8)) }.padding(.horizontal, 12).padding(.vertical, 6).background(Capsule().fill(Color.white.opacity(0.15))) }.padding(.top, 20).padding(.bottom, 32).frame(maxWidth: .infinity).background(LinearGradient(colors: [BBVA.navy, Color(hex: 0x0A3366)], startPoint: .top, endPoint: .bottom)).clipShape(UnevenRoundedRectangle(bottomLeadingRadius: 32, bottomTrailingRadius: 32)) }
    private var infoSection: some View { VStack(alignment: .leading, spacing: 16) { Text("Información personal").font(BBVAFont.title(18)).foregroundColor(BBVA.navy).padding(.horizontal, 4); VStack(spacing: 12) { InfoRow(icon: "person.fill", label: "Nombre completo", value: user.name); InfoRow(icon: "envelope.fill", label: "Correo electrónico", value: user.email); InfoRow(icon: "calendar", label: "Cliente desde", value: "Noviembre 2026") } }.padding(.vertical, 20).padding(.horizontal, 20).background(RoundedRectangle(cornerRadius: 24, style: .continuous).fill(Color.white).shadow(color: BBVA.navy.opacity(0.06), radius: 12, y: 4)) }
    private var menuSection: some View { VStack(alignment: .leading, spacing: 16) { Text("Configuración").font(BBVAFont.title(18)).foregroundColor(BBVA.navy).padding(.horizontal, 4); VStack(spacing: 2) { MenuRow(icon: "lock.shield", label: "Seguridad y acceso", tint: BBVA.coreBlue); MenuRow(icon: "bell.fill", label: "Notificaciones", tint: BBVA.midBlue); MenuRow(icon: "creditcard.fill", label: "Tarjetas", tint: Color(hex: 0x0E9AA0)) } }.padding(.vertical, 20).padding(.horizontal, 20).background(RoundedRectangle(cornerRadius: 24, style: .continuous).fill(Color.white).shadow(color: BBVA.navy.opacity(0.06), radius: 12, y: 4)) }
    private var settingsSection: some View { VStack(alignment: .leading, spacing: 16) { Text("Ajustes").font(BBVAFont.title(18)).foregroundColor(BBVA.navy).padding(.horizontal, 4); VStack(spacing: 2) { ToggleRow(label: "Modo oscuro", icon: "moon.fill"); ToggleRow(label: "Habilitar Face ID", icon: "faceid") } }.padding(.vertical, 20).padding(.horizontal, 20).background(RoundedRectangle(cornerRadius: 24, style: .continuous).fill(Color.white).shadow(color: BBVA.navy.opacity(0.06), radius: 12, y: 4)) }
    private var logoutButton: some View { Button { Haptics.tap(); showingLogoutAlert = true } label: { HStack { Image(systemName: "rectangle.portrait.and.arrow.right").font(.system(size: 18, weight: .semibold)); Text("Cerrar sesión").font(BBVAFont.body(17, .demi)) }.foregroundColor(BBVA.error).frame(maxWidth: .infinity).frame(height: 56).background(RoundedRectangle(cornerRadius: 18, style: .continuous).fill(BBVA.error.opacity(0.10))).overlay(RoundedRectangle(cornerRadius: 18, style: .continuous).stroke(BBVA.error.opacity(0.3), lineWidth: 1)) }.padding(.top, 24) }
}
struct InfoRow: View { let icon: String; let label: String; let value: String; var body: some View { HStack(spacing: 14) { Image(systemName: icon).font(.system(size: 16, weight: .medium)).foregroundColor(BBVA.coreBlue).frame(width: 24); Text(label).font(BBVAFont.body(14)).foregroundColor(BBVA.slate); Spacer(); Text(value).font(BBVAFont.body(14, .medium)).foregroundColor(BBVA.navy) }.padding(.vertical, 8) } }
struct MenuRow: View { let icon: String; let label: String; let tint: Color; var body: some View { Button { Haptics.tap() } label: { HStack(spacing: 14) { Image(systemName: icon).font(.system(size: 18, weight: .medium)).foregroundColor(tint).frame(width: 24); Text(label).font(BBVAFont.body(16, .medium)).foregroundColor(BBVA.navy); Spacer(); Image(systemName: "chevron.right").font(.system(size: 14, weight: .semibold)).foregroundColor(BBVA.line) }.padding(.vertical, 12) } } }
struct ToggleRow: View { let label: String; let icon: String; @State private var isOn = false; var body: some View { HStack(spacing: 14) { Image(systemName: icon).font(.system(size: 18, weight: .medium)).foregroundColor(BBVA.midBlue).frame(width: 24); Text(label).font(BBVAFont.body(16, .medium)).foregroundColor(BBVA.navy); Spacer(); Toggle("", isOn: $isOn).toggleStyle(SwitchToggleStyle(tint: BBVA.coreBlue)).scaleEffect(0.9) }.padding(.vertical, 12) } }
